def kare(x: int) -> int:
    return x * x

print(kare(2.5))

from typing import Optional

def ilk_cift(sayilar: list[int]) -> Optional[int]:
    for s in sayilar:
        if s % 2 == 0:
            return s
    return None

print(ilk_cift([3, 5, 8, 10]), ilk_cift([1, 3]))

def ortalama(notlar: list[float]) -> float:
    toplam = sum(notlar)
    return toplam / len(notlar)

sonuc: float = ortalama([70.0, 80.0, 90.0])
print(sonuc)

from typing import TypedDict

class Ogrenci(TypedDict):
    ad: str
    puan: int

o: Ogrenci = {"ad": "Ece", "puan": 92}
print(type(o).__name__, o["puan"])
